package com.wangc.bill.reference;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.TimeZone;
import java.util.concurrent.atomic.AtomicBoolean;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/** Typed source fixtures prove projection arithmetic, not production coverage of unported domains. */
public final class OriginalCreditProjectionTest {
    private Locale locale;private TimeZone zone;
    @Before public void dates(){locale=Locale.getDefault();zone=TimeZone.getDefault();Locale.setDefault(Locale.US);TimeZone.setDefault(TimeZone.getTimeZone("UTC"));}
    @After public void resetDates(){Locale.setDefault(locale);TimeZone.setDefault(zone);}
    private static long time(String value){return OriginalInstalmentSchedule.parse(value,"yyyy-MM-dd");}
    private OriginalCreditProjection.Asset asset(double balance){OriginalCreditProjection.Asset a=new OriginalCreditProjection.Asset();a.semanticId=99;a.balance=()->balance;return a;}
    private OriginalBillRecord bill(int id,double cost,int parent,String date){OriginalBillRecord b=new OriginalBillRecord();b.billId=id;b.assetId=99;b.cost=cost;b.parentCategoryId=parent;b.time=time(date);return b;}
    private static class Source implements OriginalCreditProjection.DataSource {
        final List<OriginalBillRecord> bills=new ArrayList<>();final List<OriginalCreditProjection.Receipt> receipts=new ArrayList<>();final List<OriginalCreditProjection.Transfer> transfers=new ArrayList<>();final List<OriginalCreditProjection.Stock> stocks=new ArrayList<>();OriginalInstalmentRecord instalment;double refund;
        public List<OriginalBillRecord> bills(long a){return bills;}public OriginalCreditProjection.RefundAdjustment refund(OriginalBillRecord b){return new OriginalCreditProjection.RefundAdjustment(refund!=0,refund);}public OriginalInstalmentRecord instalmentForBill(int b){return instalment;}public List<OriginalInstalmentRecord> instalments(long a){return Collections.emptyList();}public List<OriginalCreditProjection.Receipt> receipts(long a){return receipts;}public List<OriginalCreditProjection.Transfer> transfers(long a){return transfers;}public List<OriginalCreditProjection.Lend> lends(long a){return Collections.emptyList();}public List<OriginalCreditProjection.Stock> stocks(long a){return stocks;}public List<OriginalCreditProjection.Lend> interestRows(long a,long s,long e){return Collections.emptyList();}public OriginalBillRecord billBySemantic(int a){return null;}public Integer assetType(long a){return 1;}public String assetName(long a){return "合成账户";}public String stockName(long a){return "合成理财";}public String operationIcon(int t,String f){return f;}public int configuredMonthStart(){return 0;}public long now(){return time("2025-01-15");}public OriginalCreditBillInfo billInfo(OriginalBillRecord b){OriginalCreditBillInfo i=new OriginalCreditBillInfo();i.setBillId(b.billId);i.setTitle("合成分类");i.setDate(b.inAssetTime==0?b.time:b.inAssetTime);i.setNumber(b.parentCategoryId==9?Math.abs(b.cost):-Math.abs(b.cost));return i;}
    }
    @Test public void expenseAndIncomeNetToTheActualRemainingDebt(){Source s=new Source();s.bills.add(bill(1,12.5,99,"2025-01-01"));s.bills.add(bill(2,5,9,"2025-01-02"));OriginalCreditBill r=OriginalCreditProjection.build(asset(-7.5),s,false).statements.get(0);assertEquals(7.5,r.getNumber(),0);assertEquals(7.5,r.getRemindNumber(),0);assertFalse(r.isCurrent());assertEquals("2025-01-31",r.getRepaymentDay());assertEquals(-12.5,r.getBillInfoList().get(0).getNumber(),0);assertEquals(5,r.getBillInfoList().get(1).getNumber(),0);}
    @Test public void assetBookingTimeSelectsTheStatementWithoutChangingBillTime(){Source s=new Source();OriginalBillRecord b=bill(1,3,99,"2025-01-01");b.inAssetTime=time("2025-02-01");s.bills.add(b);OriginalCreditBill r=OriginalCreditProjection.build(asset(-3),s,false).statements.get(0);assertEquals(2,r.getMonth());assertEquals(time("2025-02-01"),r.getBillInfoList().get(0).getDate());assertEquals(time("2025-01-01"),b.time);}
    @Test public void refundGrossUpIsTemporaryAndCurrencyInfoBypassesIt(){Source s=new Source();OriginalBillRecord b=bill(1,-12,99,"2025-01-01");s.bills.add(b);s.refund=3;assertEquals(15,OriginalCreditProjection.build(asset(-15),s,false).statements.get(0).getNumber(),0);assertEquals(-12,b.cost,0);b.currencyInfo="original raw FX";b.currencyAssetNumber=8;assertEquals(8,OriginalCreditProjection.build(asset(-8),s,false).statements.get(0).getNumber(),0);assertEquals(-12,b.cost,0);}
    @Test public void instalmentLeavesTheUnfinancedPartInTheOriginalMonth(){Source s=new Source();s.bills.add(bill(1,30,99,"2025-01-01"));s.instalment=new OriginalInstalmentRecord();s.instalment.totalNumber=24;s.instalment.periods=3;s.instalment.inAssetTime=time("2025-01-01");List<OriginalCreditBill> rows=OriginalCreditProjection.build(asset(-30),s,false).statements;assertEquals(3,rows.size());assertEquals(8,rows.get(0).getNumber(),0);assertEquals(8,rows.get(1).getNumber(),0);assertEquals(14,rows.get(2).getNumber(),0);assertEquals(-6,rows.get(2).getBillInfoList().get(0).getNumber(),0);assertEquals("[1/3]合成分类",rows.get(2).getInstalmentInfoList().get(0).getTitle());}
    @Test public void receiptDetailsPreserveTheOriginalZeroBillId(){Source s=new Source();s.bills.add(bill(123,10,99,"2025-01-01"));OriginalCreditProjection.Receipt receipt=new OriginalCreditProjection.Receipt();receipt.assetId=99;receipt.time=time("2025-01-02");receipt.amount=3;receipt.type=2;s.receipts.add(receipt);OriginalCreditBill r=OriginalCreditProjection.build(asset(-7),s,false).statements.get(0);assertEquals(7,r.getNumber(),0);assertEquals(0,r.getBillInfoList().get(1).getBillId());assertEquals("退款",r.getBillInfoList().get(1).getTitle());}
    @Test public void typedTransferAndStockUseOppositeSignedDirections(){Source s=new Source();OriginalCreditProjection.Transfer t=new OriginalCreditProjection.Transfer();t.fromAssetId=99;t.toAssetId=9;t.cost=-5;t.time=time("2025-01-01");s.transfers.add(t);OriginalCreditProjection.Stock stock=new OriginalCreditProjection.Stock();stock.type=1;stock.totalCost=2;stock.doTime=t.time;s.stocks.add(stock);OriginalCreditBill r=OriginalCreditProjection.build(asset(-3),s,false).statements.get(0);assertEquals(3,r.getNumber(),0);assertEquals(-5,r.getBillInfoList().get(0).getNumber(),0);assertEquals(2,r.getBillInfoList().get(1).getNumber(),0);}
    @Test public void allocationReadsTheRetainedGetterAfterPublishingTheRealPeriods(){Source s=new Source();s.bills.add(bill(1,5,99,"2025-01-01"));AtomicBoolean published=new AtomicBoolean();OriginalCreditProjection.Asset a=asset(0);a.balance=()->{assertTrue(published.get());return -3;};final List<OriginalCreditBill> live=new ArrayList<>();OriginalCreditProjection.Result r=OriginalCreditProjection.build(a,s,false,new OriginalCreditProjection.Publication(){public void periods(List<OriginalCreditBill> rows){live.addAll(rows);published.set(true);}public void remainingServiceCost(double n){}});assertSame(r.statements.get(0),live.get(0));assertEquals(3,live.get(0).getRemindNumber(),0);}
    @Test public void publishedPeriodsSurviveAnAllocationFailure(){Source s=new Source();s.bills.add(bill(1,5,99,"2025-01-01"));OriginalCreditProjection.Asset a=asset(0);a.balance=()->{throw new IllegalStateException("synthetic getter failure");};List<OriginalCreditBill> live=new ArrayList<>();try{OriginalCreditProjection.build(a,s,false,new OriginalCreditProjection.Publication(){public void periods(List<OriginalCreditBill> rows){live.addAll(rows);}public void remainingServiceCost(double n){}});fail("Allocation failure was hidden");}catch(IllegalStateException expected){}assertEquals(1,live.size());assertEquals(5,live.get(0).getNumber(),0);assertEquals(0,live.get(0).getRemindNumber(),0);}
}
